('dabrowski', 'powiat dąbrowski', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 4.16, '%'),
('dabrowski', 'powiat dąbrowski', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.0, '%'),
('dabrowski', 'powiat dąbrowski', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.03, '%'),
('dabrowski', 'powiat dąbrowski', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 42.93, '%'),
