('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 1.81, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 33.13, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 19.56, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 23.48, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 17.29, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.66, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 8.08, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 21.49, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 32.59, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 37.18, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 78.34, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 55.01, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 1995.0, 'osoby'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 290.0, 'osoby'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 3.44, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 12.0, 'na 1000 mieszkańców'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 11.0, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 20.0, '%'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 2.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 15.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 2.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 2.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 2.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 32.0, 'mieszkania'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 8.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 39.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 26.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 7.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 11.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 2.0, 'placówki'),
('krakow', 'powiat m. Kraków', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 38.24, '%'),
('krakow', 'powiat m. Kraków', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 6.17, 'na 1000 dzieci'),
('krakow', 'powiat m. Kraków', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 380.0, 'rodziny'),
('krakow', 'powiat m. Kraków', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 497.0, 'dzieci'),
('krakow', 'powiat m. Kraków', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 2997.0, 'osób na 1 aptekę'),
('krakow', 'powiat m. Kraków', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 31.1, '%'),
('krakow', 'powiat m. Kraków', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 43.0, '%'),
('krakow', 'powiat m. Kraków', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 121.1, '% średniej krajowej'),
('krakow', 'powiat m. Kraków', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 67.0, 'osób na 1 miejsce w kinie'),
('krakow', 'powiat m. Kraków', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 1166.0, 'osób na 1 placówkę'),
('krakow', 'powiat m. Kraków', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 16858.0, 'osób na 1 muzeum'),
('krakow', 'powiat m. Kraków', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 12449.0, 'osób na 1 bibliotekę'),
('krakow', 'powiat m. Kraków', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 12.0, 'wypożyczeń na czytelnika'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 104.3, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 89.0, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 95.0, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 74.27, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 83.04, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 70.72, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 30.86, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 61.25, '%'),
('krakow', 'powiat m. Kraków', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 7.89, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 2.0, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 48.84, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 5.4, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 31.7, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 23.84, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 6.06, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 21.45, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 19.6, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 23.88, 'na 100 osób w wieku produkcyjnym'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 3.89, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 0.46, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 13.75, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 33.69, '%'),
('krakow', 'powiat m. Kraków', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 48.2, '%'),
('krakow', 'powiat m. Kraków', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, 3271.0, 'osoby'),
('krakow', 'powiat m. Kraków', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, 1141.0, 'osoby'),
('krakow', 'powiat m. Kraków', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 12204.49, 'zł na mieszkańca'),
('krakow', 'powiat m. Kraków', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 4054.46, 'zł na mieszkańca'),
('krakow', 'powiat m. Kraków', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 653.56, 'zł na mieszkańca'),
('krakow', 'powiat m. Kraków', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 820.76, 'zł na mieszkańca'),
('krakowski', 'powiat krakowski', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 304278.0, 'osoby'),
('krakowski', 'powiat krakowski', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 20.84, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 58.89, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 20.27, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 22.95, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 15.28, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 10.0, 'na 100 osób w wieku 50–64 lata'),
('krakowski', 'powiat krakowski', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 384.0, 'na 100 osób w wieku 80+'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 69.8, 'na 100 osób w wieku produkcyjnym'),
('krakowski', 'powiat krakowski', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, -1.67, 'na 1000 mieszkańców'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 103.8, 'kobiet na 100 mężczyzn'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 96.34, 'mężczyzn na 100 kobiet'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 247.3, 'osób na 1 km²'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 14.47, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.1, 'na 1000 mieszkańców'),
('krakowski', 'powiat krakowski', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 7.13, 'na 1000 mieszkańców'),
('krakowski', 'powiat krakowski', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 8.8, 'na 1000 mieszkańców'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 102.0, 'osób 65+ na 100 dzieci do 14 lat'),
('krakowski', 'powiat krakowski', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 17.39, '%'),
('krakowski', 'powiat krakowski', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 377.0, 'osób 15–64 na 100 osób 65+'),
('krakowski', 'powiat krakowski', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 2396.0, 'mieszkańców na 1 pracownika'),
('krakowski', 'powiat krakowski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 87.5, '%'),
('krakowski', 'powiat krakowski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający I stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych OPS posiadających I stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 14.84, '%'),
