('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezrobocie', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezrobocia (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 27.29, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Długotrwała lub ciężka choroba', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu długotrwałej bądź ciężkiej choroby (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 55.91, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Narkomania', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu narkomanii (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.08, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Niepełnosprawność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu niepełnosprawności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 37.38, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Potrzeba ochrony macierzyństwa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu potrzeby ochrony macierzyństwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 26.26, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 10.33, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.24, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.42, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 33.83, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Wielodzietność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu wielodzietności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 17.67, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – powody udzielania pomocy', 'Zdarzenie losowe', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu zdarzenia losowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.87, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 2.74, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 57.55, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 44.6, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 23.36, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 3.36, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.31, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 12.23, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 20.18, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 31.5, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 35.78, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 53.79, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 65.38, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 115.0, 'osoby'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 26.0, 'osoby'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 5.05, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 13.0, 'na 1000 mieszkańców'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 16.0, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 38.0, '%'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 5.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 2.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 0.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 0.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 1.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 1.0, 'mieszkania'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 1.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 3.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 5.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 0.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 4.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 1.0, 'placówki'),
('miechowski', 'powiat miechowski', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 39.68, '%'),
('miechowski', 'powiat miechowski', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 11.33, 'na 1000 dzieci'),
('miechowski', 'powiat miechowski', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 41.0, 'rodziny'),
('miechowski', 'powiat miechowski', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 57.0, 'dzieci'),
('miechowski', 'powiat miechowski', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 3308.0, 'osób na 1 aptekę'),
('miechowski', 'powiat miechowski', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 25.4, '%'),
('miechowski', 'powiat miechowski', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 42.8, '%'),
('miechowski', 'powiat miechowski', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 84.4, '% średniej krajowej'),
('miechowski', 'powiat miechowski', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 212.0, 'osób na 1 miejsce w kinie'),
('miechowski', 'powiat miechowski', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 4210.0, 'osób na 1 placówkę'),
('miechowski', 'powiat miechowski', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 46305.0, 'osób na 1 muzeum'),
('miechowski', 'powiat miechowski', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 4210.0, 'osób na 1 bibliotekę'),
('miechowski', 'powiat miechowski', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 18.0, 'wypożyczeń na czytelnika'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 92.9, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 81.0, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 88.0, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 64.51, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 62.83, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 52.3, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 56.33, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 33.54, '%'),
('miechowski', 'powiat miechowski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 10.13, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 5.2, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 52.8, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 13.75, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 41.8, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 25.06, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 20.44, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 24.82, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 11.92, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 15.85, 'na 100 osób w wieku produkcyjnym'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 0.75, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 33.51, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 11.46, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 26.6, '%'),
('miechowski', 'powiat miechowski', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 27.65, '%'),
('miechowski', 'powiat miechowski', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, -58.0, 'osoby'),
('miechowski', 'powiat miechowski', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, -1.0, 'osoby'),
('miechowski', 'powiat miechowski', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 7072.05, 'zł na mieszkańca'),
('miechowski', 'powiat miechowski', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 2325.98, 'zł na mieszkańca'),
('miechowski', 'powiat miechowski', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 295.62, 'zł na mieszkańca'),
('miechowski', 'powiat miechowski', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 643.21, 'zł na mieszkańca'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 129984.0, 'osoby'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 21.61, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 59.14, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 19.25, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 22.12, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 14.88, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 9.0, 'na 100 osób w wieku 50–64 lata'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 386.0, 'na 100 osób w wieku 80+'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 69.1, 'na 100 osób w wieku produkcyjnym'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, -0.32, 'na 1000 mieszkańców'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 101.87, 'kobiet na 100 mężczyzn'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 98.17, 'mężczyzn na 100 kobiet'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 193.1, 'osób na 1 km²'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 23.31, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.9, 'na 1000 mieszkańców'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 8.88, 'na 1000 mieszkańców'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 9.2, 'na 1000 mieszkańców'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 91.0, 'osób 65+ na 100 dzieci do 14 lat'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 16.27, '%'),
('myslenicki', 'powiat myślenicki', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 405.0, 'osób 15–64 na 100 osób 65+'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 2063.0, 'mieszkańców na 1 pracownika'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 93.44, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający I stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych OPS posiadających I stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 16.39, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający II stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych posiadających II stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 3.28, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Alkoholizm', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu alkoholizmu (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 4.34, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Bezdomność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezdomności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.25, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Bezradność w sprawach opiekuńczo-wychowawczych i prowadzenia gosp. dom.', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezradności w sprawach opiekuńczo-wychowawczych i prowadzenia gospodarstwa domowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 13.22, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Bezrobocie', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezrobocia (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 19.11, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Długotrwała lub ciężka choroba', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu długotrwałej bądź ciężkiej choroby (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 50.82, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Narkomania', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu narkomanii (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.14, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Niepełnosprawność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu niepełnosprawności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 35.1, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Potrzeba ochrony macierzyństwa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu potrzeby ochrony macierzyństwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 39.33, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 2.46, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.31, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.45, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 39.75, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Wielodzietność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu wielodzietności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 35.62, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – powody udzielania pomocy', 'Zdarzenie losowe', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu zdarzenia losowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.94, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 2.22, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 39.09, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 48.92, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 20.57, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 2.86, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.0, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 13.33, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 31.43, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 35.24, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 20.0, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 65.94, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 67.43, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 153.0, 'osoby'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 22.0, 'osoby'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 2.91, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 13.0, 'na 1000 mieszkańców'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 19.0, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 36.0, '%'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 3.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 0.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 0.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 1.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 5.0, 'mieszkania'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 0.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 2.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 8.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 6.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 4.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 0.0, 'placówki'),
('myslenicki', 'powiat myślenicki', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 74.51, '%'),
('myslenicki', 'powiat myślenicki', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 1.89, 'na 1000 dzieci'),
('myslenicki', 'powiat myślenicki', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 17.0, 'rodziny'),
('myslenicki', 'powiat myślenicki', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 38.0, 'dzieci'),
('myslenicki', 'powiat myślenicki', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 4333.0, 'osób na 1 aptekę'),
('myslenicki', 'powiat myślenicki', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 29.1, '%'),
('myslenicki', 'powiat myślenicki', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 43.0, '%'),
('myslenicki', 'powiat myślenicki', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 84.1, '% średniej krajowej'),
('myslenicki', 'powiat myślenicki', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 332.0, 'osób na 1 miejsce w kinie'),
('myslenicki', 'powiat myślenicki', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 1040.0, 'osób na 1 placówkę'),
('myslenicki', 'powiat myślenicki', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 129984.0, 'osób na 1 muzeum'),
('myslenicki', 'powiat myślenicki', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 5908.0, 'osób na 1 bibliotekę'),
('myslenicki', 'powiat myślenicki', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 18.0, 'wypożyczeń na czytelnika'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 95.9, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 85.0, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 95.0, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 67.34, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 68.87, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 59.45, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 44.32, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 35.7, '%'),
('myslenicki', 'powiat myślenicki', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 19.98, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 3.1, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 52.76, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 10.29, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 23.8, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 20.1, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 18.78, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 24.59, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 17.13, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 17.66, 'na 100 osób w wieku produkcyjnym'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 0.99, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 17.61, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 35.87, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 22.63, '%'),
('myslenicki', 'powiat myślenicki', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 22.9, '%'),
('myslenicki', 'powiat myślenicki', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, 285.0, 'osoby'),
('myslenicki', 'powiat myślenicki', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, 38.0, 'osoby'),
('myslenicki', 'powiat myślenicki', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 7418.66, 'zł na mieszkańca'),
('myslenicki', 'powiat myślenicki', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 3356.58, 'zł na mieszkańca'),
('myslenicki', 'powiat myślenicki', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 241.09, 'zł na mieszkańca'),
('myslenicki', 'powiat myślenicki', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 370.08, 'zł na mieszkańca'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 214876.0, 'osoby'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 22.71, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 59.23, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 18.06, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 21.02, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 16.58, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 10.0, 'na 100 osób w wieku 50–64 lata'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 365.0, 'na 100 osób w wieku 80+'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 68.8, 'na 100 osób w wieku produkcyjnym'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, 0.81, 'na 1000 mieszkańców'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 100.75, 'kobiet na 100 mężczyzn'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 99.26, 'mężczyzn na 100 kobiet'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 138.6, 'osób na 1 km²'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 15.69, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.9, 'na 1000 mieszkańców'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 8.8, 'na 1000 mieszkańców'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 7.99, 'na 1000 mieszkańców'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 81.0, 'osób 65+ na 100 dzieci do 14 lat'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 15.12, '%'),
('nowosadecki', 'powiat nowosądecki', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 438.0, 'osób 15–64 na 100 osób 65+'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 2066.0, 'mieszkańców na 1 pracownika'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 73.33, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający I stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych OPS posiadających I stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 18.1, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający II stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych posiadających II stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 3.81, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Alkoholizm', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu alkoholizmu (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.97, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Bezdomność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezdomności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.54, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Bezradność w sprawach opiekuńczo-wychowawczych i prowadzenia gosp. dom.', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezradności w sprawach opiekuńczo-wychowawczych i prowadzenia gospodarstwa domowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 6.18, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Bezrobocie', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezrobocia (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 21.28, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Długotrwała lub ciężka choroba', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu długotrwałej bądź ciężkiej choroby (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 34.65, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Narkomania', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu narkomanii (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.2, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Niepełnosprawność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu niepełnosprawności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 25.94, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Potrzeba ochrony macierzyństwa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu potrzeby ochrony macierzyństwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 51.35, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.03, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.08, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.14, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 34.37, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Wielodzietność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu wielodzietności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 49.3, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – powody udzielania pomocy', 'Zdarzenie losowe', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu zdarzenia losowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 3.11, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 5.48, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 18.62, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 51.67, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 21.26, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 7.47, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 5.69, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 23.13, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 37.37, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 33.81, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 57.95, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 72.51, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 392.0, 'osoby'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 39.0, 'osoby'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 0.51, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 31.0, 'na 1000 mieszkańców'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 22.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 45.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 5.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 3.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 0.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 0.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 0.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 8.0, 'mieszkania'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 0.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 3.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 18.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 2.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 4.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 2.0, 'placówki'),
('nowosadecki', 'powiat nowosądecki', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 68.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 3.4, 'na 1000 dzieci'),
('nowosadecki', 'powiat nowosądecki', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 100.0, 'rodziny'),
('nowosadecki', 'powiat nowosądecki', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 157.0, 'dzieci'),
('nowosadecki', 'powiat nowosądecki', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 4671.0, 'osób na 1 aptekę'),
('nowosadecki', 'powiat nowosądecki', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 24.8, '%'),
('nowosadecki', 'powiat nowosądecki', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 40.6, '%'),
('nowosadecki', 'powiat nowosądecki', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 79.1, '% średniej krajowej'),
('nowosadecki', 'powiat nowosądecki', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 504.0, 'osób na 1 miejsce w kinie'),
('nowosadecki', 'powiat nowosądecki', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 1628.0, 'osób na 1 placówkę'),
('nowosadecki', 'powiat nowosądecki', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 214876.0, 'osób na 1 muzeum'),
('nowosadecki', 'powiat nowosądecki', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 3907.0, 'osób na 1 bibliotekę'),
('nowosadecki', 'powiat nowosądecki', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 16.0, 'wypożyczeń na czytelnika'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 77.3, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 75.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 93.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 64.24, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 62.72, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 52.78, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 33.48, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 39.8, '%'),
('nowosadecki', 'powiat nowosądecki', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 26.72, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 7.8, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 62.39, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 19.2, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 41.2, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 12.37, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 19.0, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 28.45, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 14.2, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 14.28, 'na 100 osób w wieku produkcyjnym'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 1.19, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 22.04, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 33.61, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 21.54, '%'),
('nowosadecki', 'powiat nowosądecki', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 21.62, '%'),
('nowosadecki', 'powiat nowosądecki', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, -305.0, 'osoby'),
('nowosadecki', 'powiat nowosądecki', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, 7.0, 'osoby'),
('nowosadecki', 'powiat nowosądecki', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 7870.83, 'zł na mieszkańca'),
('nowosadecki', 'powiat nowosądecki', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 2928.38, 'zł na mieszkańca'),
('nowosadecki', 'powiat nowosądecki', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 262.45, 'zł na mieszkańca'),
('nowosadecki', 'powiat nowosądecki', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 462.02, 'zł na mieszkańca'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 189984.0, 'osoby'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 20.02, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 59.81, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 20.17, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 23.11, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 17.81, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 11.0, 'na 100 osób w wieku 50–64 lata'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 322.0, 'na 100 osób w wieku 80+'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 67.2, 'na 100 osób w wieku produkcyjnym'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, 0.01, 'na 1000 mieszkańców'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 104.77, 'kobiet na 100 mężczyzn'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 95.45, 'mężczyzn na 100 kobiet'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 128.8, 'osób na 1 km²'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 28.43, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.6, 'na 1000 mieszkańców'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 8.26, 'na 1000 mieszkańców'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 8.25, 'na 1000 mieszkańców'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 105.0, 'osób 65+ na 100 dzieci do 14 lat'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 17.16, '%'),
('nowotarski', 'powiat nowotarski', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 388.0, 'osób 15–64 na 100 osób 65+'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 2676.0, 'mieszkańców na 1 pracownika'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 76.06, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający I stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych OPS posiadających I stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 8.45, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający II stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych posiadających II stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 9.86, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Alkoholizm', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu alkoholizmu (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 5.37, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezdomność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezdomności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.51, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezradność w sprawach opiekuńczo-wychowawczych i prowadzenia gosp. dom.', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezradności w sprawach opiekuńczo-wychowawczych i prowadzenia gospodarstwa domowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 25.25, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezrobocie', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezrobocia (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 25.8, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Długotrwała lub ciężka choroba', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu długotrwałej bądź ciężkiej choroby (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 48.06, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Narkomania', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu narkomanii (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.12, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Niepełnosprawność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu niepełnosprawności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 39.54, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Potrzeba ochrony macierzyństwa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu potrzeby ochrony macierzyństwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 35.06, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 3.07, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.46, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.22, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 48.03, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Wielodzietność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu wielodzietności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 30.41, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – powody udzielania pomocy', 'Zdarzenie losowe', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu zdarzenia losowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.94, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 2.19, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 38.06, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 47.74, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 21.3, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.0, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.0, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 1.97, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 19.08, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 29.61, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 49.34, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 75.11, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 61.29, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 257.0, 'osoby'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 8.0, 'osoby'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 1.03, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 12.0, 'na 1000 mieszkańców'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 15.0, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 42.0, '%'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 2.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 0.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 0.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 2.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 3.0, 'mieszkania'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 1.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 4.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 8.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 5.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 5.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 1.0, 'placówki'),
('nowotarski', 'powiat nowotarski', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 78.47, '%'),
('nowotarski', 'powiat nowotarski', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 5.55, 'na 1000 dzieci'),
('nowotarski', 'powiat nowotarski', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 121.0, 'rodziny'),
('nowotarski', 'powiat nowotarski', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 193.0, 'dzieci'),
('nowotarski', 'powiat nowotarski', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 3654.0, 'osób na 1 aptekę'),
('nowotarski', 'powiat nowotarski', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 27.1, '%'),
('nowotarski', 'powiat nowotarski', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 38.3, '%'),
('nowotarski', 'powiat nowotarski', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 79.8, '% średniej krajowej'),
('nowotarski', 'powiat nowotarski', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 287.0, 'osób na 1 miejsce w kinie'),
('nowotarski', 'powiat nowotarski', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 2184.0, 'osób na 1 placówkę'),
('nowotarski', 'powiat nowotarski', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 37997.0, 'osób na 1 muzeum'),
('nowotarski', 'powiat nowotarski', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 3393.0, 'osób na 1 bibliotekę'),
('nowotarski', 'powiat nowotarski', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 15.0, 'wypożyczeń na czytelnika'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 89.6, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 93.0, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 90.0, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 63.75, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 61.01, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 49.84, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 34.53, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 32.08, '%'),
('nowotarski', 'powiat nowotarski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 33.39, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 4.8, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 46.36, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 15.84, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 23.7, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 25.21, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 19.1, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 25.67, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 14.55, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 15.62, 'na 100 osób w wieku produkcyjnym'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 1.28, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 27.28, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 26.48, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 20.66, '%'),
('nowotarski', 'powiat nowotarski', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 24.3, '%'),
('nowotarski', 'powiat nowotarski', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, -107.0, 'osoby'),
('nowotarski', 'powiat nowotarski', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, 41.0, 'osoby'),
('nowotarski', 'powiat nowotarski', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 7138.41, 'zł na mieszkańca'),
('nowotarski', 'powiat nowotarski', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 2806.26, 'zł na mieszkańca'),
('nowotarski', 'powiat nowotarski', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 233.46, 'zł na mieszkańca'),
('nowotarski', 'powiat nowotarski', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 315.18, 'zł na mieszkańca'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 79821.0, 'osoby'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 18.75, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 56.72, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 24.53, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 27.38, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 16.99, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 13.0, 'na 100 osób w wieku 50–64 lata'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 302.0, 'na 100 osób w wieku 80+'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 76.3, 'na 100 osób w wieku produkcyjnym'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, -2.99, 'na 1000 mieszkańców'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 109.67, 'kobiet na 100 mężczyzn'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 91.18, 'mężczyzn na 100 kobiet'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 1385.8, 'osób na 1 km²'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 100.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.2, 'na 1000 mieszkańców'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 7.25, 'na 1000 mieszkańców'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 10.24, 'na 1000 mieszkańców'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 141.0, 'osób 65+ na 100 dzieci do 14 lat'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 21.12, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 302.0, 'osób 15–64 na 100 osób 65+'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 1698.0, 'mieszkańców na 1 pracownika'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 96.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający I stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych OPS posiadających I stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 6.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający II stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych posiadających II stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 2.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Alkoholizm', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu alkoholizmu (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 7.49, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Bezdomność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezdomności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 2.91, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Bezradność w sprawach opiekuńczo-wychowawczych i prowadzenia gosp. dom.', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezradności w sprawach opiekuńczo-wychowawczych i prowadzenia gospodarstwa domowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 43.19, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Bezrobocie', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezrobocia (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 47.73, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Długotrwała lub ciężka choroba', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu długotrwałej bądź ciężkiej choroby (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 65.5, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Narkomania', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu narkomanii (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.36, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Niepełnosprawność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu niepełnosprawności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 49.16, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Potrzeba ochrony macierzyństwa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu potrzeby ochrony macierzyństwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 18.88, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 26.77, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.08, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 3.07, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 60.2, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Wielodzietność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu wielodzietności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 17.61, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – powody udzielania pomocy', 'Zdarzenie losowe', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu zdarzenia losowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.24, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 3.14, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 38.65, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 36.71, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 27.07, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 13.23, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.31, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 6.77, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 24.62, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 36.31, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 32.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 85.98, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 55.94, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 294.0, 'osoby'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 22.0, 'osoby'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 3.71, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 14.0, 'na 1000 mieszkańców'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 15.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 23.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 3.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 0.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 0.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 2.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 4.0, 'mieszkania'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 1.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 6.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 14.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 0.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 0.0, 'placówki'),
('nowysacz', 'powiat m. Nowy Sącz', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 68.38, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 11.49, 'na 1000 dzieci'),
('nowysacz', 'powiat m. Nowy Sącz', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 56.0, 'rodziny'),
('nowysacz', 'powiat m. Nowy Sącz', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 85.0, 'dzieci'),
('nowysacz', 'powiat m. Nowy Sącz', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 2348.0, 'osób na 1 aptekę'),
('nowysacz', 'powiat m. Nowy Sącz', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 29.7, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 37.9, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 84.4, '% średniej krajowej'),
('nowysacz', 'powiat m. Nowy Sącz', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 45.0, 'osób na 1 miejsce w kinie'),
('nowysacz', 'powiat m. Nowy Sącz', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 7982.0, 'osób na 1 placówkę'),
('nowysacz', 'powiat m. Nowy Sącz', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 26607.0, 'osób na 1 muzeum'),
('nowysacz', 'powiat m. Nowy Sącz', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 9978.0, 'osób na 1 bibliotekę'),
('nowysacz', 'powiat m. Nowy Sącz', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 20.0, 'wypożyczeń na czytelnika'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 121.3, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 90.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 95.0, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 65.7, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 71.27, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 55.06, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 39.35, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 46.76, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 13.89, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 3.5, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 54.74, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 16.2, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 26.9, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 20.55, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 13.57, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 22.28, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 17.48, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 17.73, 'na 100 osób w wieku produkcyjnym'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 2.31, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 0.58, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 34.76, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 25.9, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 36.45, '%'),
('nowysacz', 'powiat m. Nowy Sącz', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, -293.0, 'osoby'),
('nowysacz', 'powiat m. Nowy Sącz', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, 30.0, 'osoby'),
('nowysacz', 'powiat m. Nowy Sącz', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 10949.81, 'zł na mieszkańca'),
('nowysacz', 'powiat m. Nowy Sącz', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 5018.74, 'zł na mieszkańca'),
('nowysacz', 'powiat m. Nowy Sącz', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 181.95, 'zł na mieszkańca'),
('nowysacz', 'powiat m. Nowy Sącz', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 1033.38, 'zł na mieszkańca'),
('olkuski', 'powiat olkuski', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 105000.0, 'osoby'),
('olkuski', 'powiat olkuski', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 16.49, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 56.47, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 27.04, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 30.1, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 16.11, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 13.0, 'na 100 osób w wieku 50–64 lata'),
('olkuski', 'powiat olkuski', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 292.0, 'na 100 osób w wieku 80+'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 77.1, 'na 100 osób w wieku produkcyjnym'),
('olkuski', 'powiat olkuski', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, -6.59, 'na 1000 mieszkańców'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 106.27, 'kobiet na 100 mężczyzn'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 94.1, 'mężczyzn na 100 kobiet'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 169.9, 'osób na 1 km²'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 46.85, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.3, 'na 1000 mieszkańców'),
('olkuski', 'powiat olkuski', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 5.94, 'na 1000 mieszkańców'),
('olkuski', 'powiat olkuski', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 12.53, 'na 1000 mieszkańców'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 177.0, 'osób 65+ na 100 dzieci do 14 lat'),
('olkuski', 'powiat olkuski', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 23.56, '%'),
('olkuski', 'powiat olkuski', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 268.0, 'osób 15–64 na 100 osób 65+'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 1981.0, 'mieszkańców na 1 pracownika'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 88.68, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający I stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych OPS posiadających I stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 13.21, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający II stopień specjalizacji w zawodzie pracownik socjalny', 'Udział pracowników socjalnych posiadających II stopień specjalizacji w zawodzie pracownik socjalny w ogólnej liczbie pracowników socjalnych.', 2024, 13.21, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Alkoholizm', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu alkoholizmu (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 4.79, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezdomność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezdomności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 2.96, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezradność w sprawach opiekuńczo-wychowawczych i prowadzenia gosp. dom.', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezradności w sprawach opiekuńczo-wychowawczych i prowadzenia gospodarstwa domowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 16.58, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Bezrobocie', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu bezrobocia (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 33.2, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Długotrwała lub ciężka choroba', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu długotrwałej bądź ciężkiej choroby (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 35.22, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Narkomania', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu narkomanii (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.36, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Niepełnosprawność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu niepełnosprawności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 29.09, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Potrzeba ochrony macierzyństwa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu potrzeby ochrony macierzyństwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 12.15, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Przemoc domowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu przemocy domowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 1.69, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Sieroctwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sieroctwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.11, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Sytuacja kryzysowa', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu sytuacji kryzysowej (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.04, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Ubóstwo', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu ubóstwa (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 41.67, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Wielodzietność', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu wielodzietności (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 9.77, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – powody udzielania pomocy', 'Zdarzenie losowe', 'Odsetek klientów pomocy społecznej korzystających ze wsparcia z powodu zdarzenia losowego (na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną).', 2024, 0.72, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Beneficjenci pomocy społecznej', 'Udział osób korzystających z pomocy społecznej w liczbie ludności ogółem - na podstawie danych o rzeczywistej liczbie osób w rodzinach objętych pomocą społeczną (świadczenia przyznane w ramach zadań zleconych i własnych bez względu na rodzaj, formę, liczbę oraz źródło finansowania).', 2024, 2.64, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Rodziny niepełne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom niepełnym - udział rodzin niepełnych objętych pomocą (w której skład wchodzi jedno z rodziców z dzieckiem/ dziećmi) w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 73.17, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Rodziny wielodzietne objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom wielodzietnym - udział rodzin wielodzietnych (3 dzieci i więcej) objętych pomocą w liczbie wszystkich rodzin z dziećmi, którym udzielono pomocy.', 2024, 28.05, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Rodziny emerytów i rencistów objęte pomocą społeczną', 'Wskaźnik pomocy społecznej udzielonej rodzinom emerytów i rencistów - udział rodzin emerytów i rencistów objętych pomocą w liczbie wszystkich rodzin, którym udzielono pomocy.', 2024, 24.04, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS nieopuszczający łóżek', 'Odsetek pensjonariuszy Domów Pomocy Społecznej nieopuszczających łóżek. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 20.41, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS do 18 roku życia', 'Odsetek pensjonariuszy Domów Pomocy Społecznej w wieku do18 roku życia. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 0.0, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 19-40 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 19-40 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 4.08, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 41-60 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 41-60 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 20.41, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku 61-74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku 60-74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 47.96, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – beneficjenci', 'Pensjonariusze DPS w wieku powyżej 74 lat', 'Odsetek pensjonariuszy Domów Pomocy Społecznej wieku powyżej 74 lat. Dane na temat liczby mieszkańców Domów Pomocy Społecznej zebrano wg. stanu na dzień 31 grudnia. W statystykach uwzględniono mieszkańców Domów Pomocy Społecznej i podmiotów niepublicznych w roku sprawozdawczym.', 2024, 27.55, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia pieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń pieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 75.16, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Świadczenia niepieniężne z pomocy społecznej', 'Odsetek korzystających ze świadczeń niepieniężnych w ogólnej liczbie świadczeniobiorców pomocy społecznej (liczba osób w rodzinach)', 2024, 39.29, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające z usług opiekuńczych i specjalistycznych usług opiekuńczych', 'Liczba osób korzystających z usług opiekuńczych (w tym specjalistycznych usług opiekuńczych).', 2024, 297.0, 'osoby'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby korzystające ze specjalistycznych usług opiekuńczych dla osób z zaburzeniami psychicznymi', 'Liczba osób korzystających ze specjalistycznych usług opiekuńczych w miejscu zamieszkania dla osób z zaburzeniami psychicznymi.', 2024, 2.0, 'osoby'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte kontraktami socjalnymi', 'Udział osób objętych kontraktami socjalnymi w ogólnej liczbie osób w rodzinach świadczeniobiorców pomocy społecznej.', 2024, 7.5, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Osoby objęte dożywianiem na 1000 mieszkańców', 'Wskaźnik pomocy w zakresie dożywiania - liczba osób objętych pomocą państwa w zakresie dożywiania w przeliczeniu na 1000 mieszkańców.', 2024, 11.0, 'na 1000 mieszkańców'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Udział dzieci w ogóle osób objętych dożywianiem', 'Udział dzieci w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania. Sprawozdanie z realizacji programu "Pomoc Państwa w zakresie dożywiania" do 2013 roku obejmowało dzieci do lat 7. Od 2014 roku w sprawozdaniu liczba dzieci jest określona na podstawie momentu rozpoczęcia nauki w szkole podstawowej.', 2024, 20.0, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna – świadczenia i usługi', 'Udział uczniów w ogóle osób objętych dożywianiem', 'Udział dzieci w wieku szkolnym (uczniowie do czasu ukończenia szkoły ponadgimnazjalnej) w liczbie wszystkich osób objętych pomocą państwa w zakresie dożywiania.', 2024, 25.0, '%'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Centra integracji społecznej', 'Liczba centrów integracji społecznej działających na danym terenie. Stan na 31 XII.', 2024, 1.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Domy pomocy społecznej', 'Liczba domów pomocy społecznej działających na danym terenie (bez podziału na typy).', 2024, 1.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Dzienne domy pomocy', 'Liczba dziennych domów pomocy działających na danym terenie. Stan na 31 XII.', 2024, 3.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa - jednostki  powiatowe', 'Liczba jednostek specjalistycznego poradnictwa działających w powiatach. Stan na 31 XII. Wskaźnik zasilany od 2021 r. w związku ze zmianami monitorowania danych w sprawozdaniach resortowych. Zastąpił on wskaźnik "Placówki specjalistycznego poradnictwa"', 2024, 0.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Placówki specjalistycznego poradnictwa', 'Liczba jednostek specjalistycznego poradnictwa działających na danym terenie. Stan na 31 XII. Od 2021 roku ze względu na brak kontynuacji monitorowania danych w sprawozdaniach resortowych wskaźnik nie jest już aktualizowany.', 2024, 0.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Kluby integracji społecznej', 'Liczba klubów integracji społecznej działających na danym terenie.', 2024, 2.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Mieszkania treningowe oraz wspomagane', 'Liczba mieszkań treningowe oraz wspomaganych działających na danym terenie. Stan na 31 XII. Do 2022 r. w systemie funkcjonowały mieszkania chronione, natomiast od 2023 r. funkcjonują mieszkania treningowe oraz wspomagane.', 2024, 7.0, 'mieszkania'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Noclegownie, schroniska i domy dla osób bezdomnych', 'Liczba noclegowni, schronisk i domów dla osób bezdomnych działających na danym terenie.', 2024, 2.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Ośrodki interwencji kryzysowej', 'Liczba ośrodków interwencji kryzysowej działających na danym terenie. Stan na 31 XII.', 2024, 0.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Placówki opiekuńczo-wychowawcze', 'Liczba placówek opiekuńczo-wychowawczych działających na danym terenie (bez podziału na typy). Stan na 31 XII.', 2024, 2.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Placówki wsparcia dziennego', 'Liczba placówek wsparcia dziennego działających na danym terenie. Stan na 31 XII.', 2024, 4.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Placówki zapewniające całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku', 'Liczba placówek zapewniających całodobową opiekę osobom niepełnosprawnym, przewlekle chorym lub osobom w podeszłym wieku działających na danym terenie (w oparciu zarówno o działalność gospodarczą, jak i o działalność statutową). Stan na 31 XII.', 2024, 5.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Środowiskowe domy samopomocy', 'Liczba środowiskowych domów samopomocy działających na danym terenie. Stan na 31 XII.', 2024, 4.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Pomoc społeczna i opieka – instytucje', 'Zakłady aktywności zawodowej', 'Liczba zakładów aktywności zawodowej działających na danym terenie.', 2024, 1.0, 'placówki'),
('olkuski', 'powiat olkuski', 'Piecza zastępcza', 'Stopień deinstytucjonalizacji pieczy zastępczej', 'Stosunek liczby dzieci w rodzinnej pieczy zastępczej (dzieci przebywające w rodzinach zastępczych, rodzinnych domach dziecka i w placówkach opiekuńczo-wychowawczych typu rodzinnego) do liczby wszystkich dzieci w pieczy zastępczej. Do wskaźnika nie wliczono dzieci umieszczonych w rodzinach zastępczych spokrewnionych (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 57.89, '%'),
('olkuski', 'powiat olkuski', 'Piecza zastępcza', 'Intensywność pieczy zastępczej', 'Liczba dzieci poniżej 18. roku życia przebywających w pieczy zastępczej w stosunku do liczby wszystkich dzieci w wieku poniżej 18 roku życia na danym terenie w przeliczeniu na 1000 dzieci (definicja zaczerpnięta z raportu "Postępy deinstytucjonalizacji pieczy zastępczej"; Warszawa 2018 r.). Dane zbierane przez MRiPS regularnie (co pół roku) w sprawozdaniach resortowych.', 2024, 6.7, 'na 1000 dzieci'),
('olkuski', 'powiat olkuski', 'Piecza zastępcza', 'Liczba rodzin zastępczych', 'Liczba rodzin zastępczych funkcjonujących na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców.', 2024, 84.0, 'rodziny'),
('olkuski', 'powiat olkuski', 'Piecza zastępcza', 'Liczba dzieci w rodzinach zastępczych', 'Liczba dzieci wychowujących się w rodzinach zastępczych na danym obszarze. Rodzina zastępcza jest jedną z form rodzinnej pieczy zastępczej, sprawowanej w przypadku niemożności zapewnienia dziecku opieki i wychowania przez rodziców. Do roku 2011 dane pochodzą ze sprawozdania MPiPS-03; od roku 2012 dane pochodzą ze sprawozdania Ocena Zasobów Pomocy Społecznej.', 2024, 98.0, 'dzieci'),
('olkuski', 'powiat olkuski', 'Zdrowie', 'Dostępność aptek', 'Wskaźnik dostępności do aptek - liczba osób przypadająca na jedną aptekę ogólnodostępną. Apteka, zgodnie z Ustawą "Prawo farmaceutyczne" z dnia 6 września 2001 r. to placówka ochrony zdrowia publicznego, w której osoby uprawnione świadczą w szczególności usługi farmaceutyczne obejmujące zadania określone w ustawie.', 2024, 3281.0, 'osób na 1 aptekę'),
('olkuski', 'powiat olkuski', 'Zdrowie', 'Zgony z powodu chorób nowotworowych', 'Wskaźnik umieralności z powodu choroby nowotworowej - udział zgonów z powodu choroby nowotworowej w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 25.9, '%'),
('olkuski', 'powiat olkuski', 'Zdrowie', 'Zgony z powodu chorób układu krążenia', 'Wskaźnik umieralności z powodu chorób układu krążenia - udział zgonów z powodu chorób układu krążenia w liczbie zgonów ogółem. Dane do wskaźnika pochodzą z kart statystycznych do kart zgonów.', 2024, 39.6, '%'),
('olkuski', 'powiat olkuski', 'Wynagrodzenia, emerytury i renty', 'Przeciętne wynagrodzenie w relacji do śr. krajowej', 'Wskaźnik wysokości wynagrodzeń - przeciętne miesięczne wynagrodzenia brutto w gospodarce narodowej w relacji do średniej krajowej (Polska=100%). Wskaźnik pokazuje jaki procent średniej krajowej jest osiągany na danym terenie.', 2024, 86.8, '% średniej krajowej'),
('olkuski', 'powiat olkuski', 'Kultura', 'Wskaźnik dostępności kin', 'Wskaźnik dostępności kin - liczba osób przypadających na jedno miejsce na widowni kina. Przez "miejsce na widowni" rozumie się każde numerowane miejsce (zarejestrowane) wykorzystywane przez instytucję kultury do stałych prezentacji scenicznych (w stałej sali eksploatowanej przez instytucję artystyczną lub w kinie stałym do prezentacji filmów).', 2024, 144.0, 'osób na 1 miejsce w kinie'),
('olkuski', 'powiat olkuski', 'Kultura', 'Wskaźnik dostępności domów i ośrodków kultury', 'Wskaźnik dostępności domów i ośrodków kultury oraz klubów, świetlic i kół - liczba osób przypadająca na jedną placówkę kultury.', 2024, 1082.0, 'osób na 1 placówkę'),
('olkuski', 'powiat olkuski', 'Kultura', 'Wskaźnik dostępności muzeów', 'Wskaźnik dostępności do muzeów - liczba ludności przypadająca na jedną placówkę muzealną. Dane wskaźnikowe bazują na sprawozdaniach z działalności muzeów i instytucji paramuzealnych. Przez placówkę muzealną (za ustawą z dnia 21 listopada 1996 r. o muzeach) rozumiemy jednostkę organizacyjną, nienastawioną na osiąganie zysku, której celem jest sprawowanie opieki nad zabytkami, informowanie o wartościach i treściach gromadzonych zbiorów, upowszechnianie podstawowych wartości historii, nauki i kultury polskiej oraz światowej, kształtowanie wrażliwości poznawczej i estetycznej oraz umożliwianie kontaktu ze zbiorami.', 2024, 105000.0, 'osób na 1 muzeum'),
('olkuski', 'powiat olkuski', 'Kultura', 'Wskaźnik dostępności bibliotek', 'Wskaźnik dostępności bibliotek - liczba ludności przydająca na jedną placówkę biblioteczną. W celu wyliczenia wskaźnika zliczono biblioteki, filie i punkty biblioteczne na danym ternie. Dane bazują na sprawozdaniach bibliotek ogólnych. Zgodnie z definicją przyjętą przez GUS przez placówkę biblioteczną rozumie się jednostkę organizacyjną lub jej część posiadającą uporządkowany (zinwentaryzowany) zbiór książek, czasopism i innych materiałów piśmienniczych liczący co najmniej 300 jednostek inwentarzowych, której głównymi celami są tworzenie i obsługa zbiorów oraz udostępnianie ich użytkownikom w sposób kontrolowany.', 2024, 4375.0, 'osób na 1 bibliotekę'),
('olkuski', 'powiat olkuski', 'Kultura', 'Wskaźnik czytelnictwa', 'Wskaźnik czytelnictwa - ilość wypożyczeń z księgozbioru przez jednego czytelnika w ciągu roku. Przez księgozbiór rozumie się zbiór obejmujący wydawnictwa nieperiodyczne (książki i broszury) i wydawnictwa periodyczne (gazety i czasopisma).', 2024, 21.0, 'wypożyczeń na czytelnika'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Edukacja przedszkolna', 'Wskaźnik edukacji na poziomie przedszkolnym - odsetek dzieci w wieku od 3 do 5 lat uczęszczających do placówek wychowania przedszkolnego. Wskaźnik zbudowano na podstawie sprawozdań przedszkoli i innych form edukacji przedszkolnej. Uwzględniono ośrodki wychowania przedszkolnego prowadzone przez ograny samorządu terytorialnego, jednostki samorządu powiatowego oraz gminnego.', 2024, 96.4, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Zdawalność egzaminu maturalnego w technikach', 'Wskaźnik zdawalności matur w technikach - procent uczniów klas IV techników, którzy zdali egzamin maturalny.', 2024, 93.0, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Zdawalność egzaminu maturalnego w liceach ogólnokształcących', 'Wskaźnik zdawalności matur w liceach -procent uczniów klas III liceów ogólnokształcących, którzy zdali egzamin maturalny.', 2024, 96.0, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język polski', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z języka polskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 64.35, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – język angielski podstawowy', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części podstawowej z języka angielskiego (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 69.16, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Wyniki egzaminu ósmoklasisty – matematyka', 'Wyrażony w % średni wynik uczniów uzyskiwany na egzaminie ósmoklasisty w części z matematyki (wskaźnik aktualizowany od 2019 roku, w którym uczniowie szkół podstawowych po raz pierwszy przystąpili do egzaminu ósmoklasisty)', 2024, 54.65, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – technikum', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali technikum jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej technikum. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 32.99, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – liceum ogólnokształcące', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali liceum ogólnokształcące jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej liceów ogólnokształcących. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 43.71, '%'),
('olkuski', 'powiat olkuski', 'Edukacja', 'Wybory edukacyjne ósmoklasistów – szkoła branżowa I stopnia', 'Wyrażony w % udział absolwentów szkół podstawowych, którzy wybrali szkołę branżową I stopnia jako miejsce dalszego kształcenia. Wskaźnik obliczony na podstawie liczby uczniów w klasie pierwszej szkół branżowych I stopnia. (wskaźnik aktualizowany od 2020 roku po ostatecznym wygaszeniu szkół gimnazjalnych)', 2024, 23.3, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Stopa bezrobocia', 'Stopa bezrobocia - procentowy udział liczby bezrobotnych w liczbie ludności aktywnej zawodowo (tzn. pracującej i bezrobotnej). Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 6.7, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobocie kobiet', 'Bezrobocie kobiet - Wyrażony w % udział bezrobotnych kobiet w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 47.54, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobocie rodzinne', 'Odsetek osób bezrobotnych zamieszkujących gospodarstwo domowe, w którym dwie lub więcej osób pozostaje na bezrobociu. Dane dla powiatu tarnowskiego i Tarnowa przedstawione zostały łącznie. Dane obrazują stan na 31 XII danego roku.', 2024, 10.06, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobotni dłużej niż 1 rok', 'Wyrażony w % udział bezrobotnych dłużej niż 1 rok w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 43.5, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobotni z wykształceniem gimnazjalnym i niższym', 'Wyrażony w % udział bezrobotnych z wykształceniem gimnazjalnym i niższym w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 20.41, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobotni w wieku poniżej 25 lat', 'Wyrażony w % udział bezrobotnych poniżej 25. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 12.61, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobotni w wieku 25-34 lata', 'Wyrażony w % udział bezrobotnych w wieku 25-34 lata w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 21.76, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Bezrobotni w wieku 55 lat i więcej', 'Wyrażony w % udział bezrobotnych powyżej 55. roku życia w liczbie bezrobotnych ogółem. Do kategorii osób bezrobotnych wlicza się wyłącznie osoby zarejestrowane w powiatowych urzędach pracy. Przez bezrobotnych ( za Ustawą z dnia 20 kwietnia 2004 r. o promocji zatrudnienia i instytucjach rynku pracy) rozumiemy osoby niezatrudnione i nie wykonujące innej pracy zarobkowej, zdolne i gotowe do podjęcia zatrudnienia w pełnym wymiarze czasu pracy (bądź jeśli są to osoby niepełnosprawne - zdolne i gotowe do podjęcia zatrudnienia co najmniej w połowie tego wymiaru czasu pracy), nieuczące się w szkole z wyjątkiem szkół dla dorosłych lub szkół wyższych w systemie wieczorowym albo zaocznym, zarejestrowane we właściwym dla miejsca zameldowania (stałego lub czasowego) powiatowym urzędzie pracy oraz poszukujące zatrudnienia lub innej pracy zarobkowej, jeżeli spełniają określone w Ustawie warunki.', 2024, 15.05, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Prowadzący działalność gospodarczą', 'Osoby fizyczne prowadzące działalność gospodarczą na 100 osób w wieku produkcyjnym. Dane bez osób prowadzących gospodarstwa indywidualne w rolnictwie.', 2024, 18.19, 'na 100 osób w wieku produkcyjnym'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Zatrudnienie w branży finansowej i nieruchomościach', 'Wyrażony w % udział pracujących w branży finansowej i nieruchomościach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Działalność finansowa i ubezpieczeniowa; obsługa rynku nieruchomości". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 2.15, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Zatrudnienie w rolnictwie', 'Wyrażony w % udział pracujących w rolnictwie w stosunku do ogółu pracujących. Dane łącznie z rolnictwem indywidualnym. Dane dotyczące pracujących w gospodarstwach indywidualnych w rolnictwie według stanu w dniu 31 XII w latach 2002-2009 wyszacowano na podstawie wyników Narodowego Spisu Powszechnego Ludności i Mieszkań oraz Powszechnego Spisu Rolnego 2002 oraz w 2010 r. na podstawie Powszechnego Spisu Rolnego 2010. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Rolnictwo, leśnictwo, łowiectwo i rybactwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 6.91, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Zatrudnienie w przemyśle i budownictwie', 'Wyrażony w % udział pracujących w przemyśle i budownictwie w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Przemysł i budownictwo" rozumie się sekcje: "Górnictwo i wydobywanie"; "Przetwórstwo przemysłowe"; "Wytwarzanie i zaopatrywanie w energię elektryczną, gaz, parę wodną i gorącą wodę"; "Dostawa wody; gospodarowanie ściekami i odpadami; rekultywacja" oraz "Budownictwo". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 41.86, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Zatrudnienie w handlu, transporcie, turystyce, informacji i komunikacji', 'Wyrażony w % udział pracujących w handlu, transporcie, turystyce, informacji i komunikacji w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Dotyczy sekcji: "Handel"; "Naprawa pojazdów samochodowych"; "Transport i gospodarka magazynowa"; "Zakwaterowanie i gastronomia" oraz "Informacja i komunikacja". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 23.82, '%'),
('olkuski', 'powiat olkuski', 'Rynek pracy', 'Zatrudnienie w pozostałych usługach', 'Wyrażony w % udział pracujących w pozostałych usługach w stosunku do ogółu pracujących. Dane do 2021 roku bez podmiotów gospodarczych o liczbie pracujących do 9 osób. Podział branż jest zgodny z PKD 2007. Pod pojęciem "Pozostałe usługi" rozumie się sekcje: "Działalność profesjonalna, naukowa i techniczna"; "Administrowanie i działalność wspierająca"; "Administracja publiczna i obrona narodowa, obowiązkowe zabezpieczenia społeczne"; "Edukacja"; "Opieka zdrowotna i pomoc społeczna"; "Działalność związana z kulturą rozrywką i rekreacją" oraz "Pozostała działalność usługowa". W związku z wprowadzonymi zmianami metodologicznymi w pozyskiwaniu danych dotyczących: pracujących, zatrudnionych oraz przeciętnego zatrudnienia według PKD, dane od 2022 roku nie mogą być porównywane z danymi dla lat poprzednich.', 2024, 25.05, '%'),
('olkuski', 'powiat olkuski', 'Mobilność', 'Saldo migracji stałych', 'Wskaźnik migracji stałych - różnica między napływem a odpływem ludności z danego obszaru w danym czasie. Saldo migracji stałych uwzględnia zarazem dane ze stałych migracji zewnętrznych jak i wewnętrznych. Migracje stałe to takie, które wiążą się ze zmianą miejsca zamieszkania na pobyt stały. W świetle prawa polskiego, tego typu migracje związane są z dokonaniem w biurze ewidencji ludności zameldowania lub wymeldowania. W 2015 roku GUS zrezygnował z opublikowania danych dotyczących migracji zagranicznych z powodu braku ich kompletności. Dlatego niemożliwe było określenie poziomu migracji stałych za rok 2015.', 2024, -202.0, 'osoby'),
('olkuski', 'powiat olkuski', 'Mobilność', 'Saldo migracji zagranicznych', 'Wskaźnik migracji zagranicznych - różnica między odpływem zagranicę a napływem do kraju ludności w danym czasie.', 2024, 22.0, 'osoby'),
('olkuski', 'powiat olkuski', 'Budżety gmin', 'Wydatki budżetów gmin ogółem', 'Wskaźnik wydatków gmin - wydatki budżetów gmin i miast na prawach powiatów w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków na rolnictwo, transport, gospodarkę komunalną, gosp. mieszkaniową, oświatę i wychowanie, kulturę i sztukę, ochronę zdrowia, kulturę fizyczną i sport, a także wydatki na administrację samorządową. Wydatki te są sklasyfikowane w rozporządzeniu Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 7229.09, 'zł na mieszkańca'),
('olkuski', 'powiat olkuski', 'Budżety gmin', 'Wydatki budżetów gmin - oświata i wychowanie', 'Wskaźnik wydatków gmin na oświatę i wychowanie - wydatki budżetów gmin i miast na prawach powiatów na oświatę i wychowanie w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 801 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 2636.95, 'zł na mieszkańca'),
('olkuski', 'powiat olkuski', 'Budżety gmin', 'Wydatki budżetów gmin - kultura', 'Wskaźnik wydatków gmin na kulturę i ochronę dziedzictwa narodowego - wydatki budżetów gmin i miast na prawach powiatów na kulturę i ochronę dziedzictwa narodowego w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w dziale 921 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Wartości podawane są w złotówkach.', 2024, 292.24, 'zł na mieszkańca'),
('olkuski', 'powiat olkuski', 'Budżety gmin', 'Wydatki budżetów gmin - pomoc społeczna', 'Wskaźnik wydatków gmin na pomoc społeczną - wydatki budżetów gmin i miast na prawach powiatów na pomoc społeczną i pozostałe zadania w zakresie polityki społecznej w przeliczeniu na jednego mieszkańca. Dane stanowią sumę wydatków sklasyfikowanych w działach 852 i 853 rozporządzenia Ministra Finansów z dnia 14 czerwca 2006 r. w sprawie szczegółowej klasyfikacji dochodów, wydatków, przychodów i rozchodów oraz środków pochodzących ze źródeł zagranicznych (Dz. U. 2006 r. Nr 107, poz.726, z późn. zm.). Dane podawane są w złotówkach.', 2024, 439.3, 'zł na mieszkańca'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Ludność ogółem', 'Liczba ludności zamieszkałej na danym terenie (dane zgodnie z faktycznym miejscem zamieszkania wg podziału administracyjnego na dzień 31 XII).', 2024, 147678.0, 'osoby'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Ludność w wieku przedprodukcyjnym', 'Udział ludności w wieku przedprodukcyjnym w liczbie ludności ogółem. Przez ludność w wieku przedprodukcyjnym rozumie się ludność w wieku do 17 roku życia.', 2024, 17.69, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Ludność w wieku produkcyjnym', 'Udział ludności w wieku produkcyjnym w liczbie ludności ogółem. Przez ludność w wieku produkcyjnym rozumie się ludność w wieku zdolności do pracy. Dla mężczyzn przyjęto wiek 18-64 lata, dla kobiet 18-59 lat.', 2024, 57.39, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Ludność w wieku poprodukcyjnym', 'Udział ludności w wieku emerytalnym w liczbie ludności ogółem. Przez ludność w wieku poprodukcyjnym rozumie się ludność w wieku od 64 lat - dla mężczyzn i od 59 lat - dla kobiet.', 2024, 24.92, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Ludność w wieku 60+', 'Udział ludności w wieku 60 i więcej lat w liczbie ludności ogółem.', 2024, 28.08, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik podwójnego starzenia', 'Udział osób w wieku 80 i więcej lat w grupie osób wieku 60 i więcej lat.', 2024, 17.51, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik wsparcia osób najstarszych', 'Liczba osób w wieku 85 lat i więcej przypadająca na 100 osób w wieku 50–64 lata', 2024, 13.0, 'na 100 osób w wieku 50–64 lata'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Potencjał pielęgnacyjny', 'Liczba kobiet w wieku 45-64 lata (potencjalnych opiekunów rodzinnych) przypadających na 100 osób w wieku 80 i więcej lat', 2024, 285.0, 'na 100 osób w wieku 80+'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik obciążenia demograficznego', 'Wskaźnik obciążenia demograficznego - ludność w wieku nieprodukcyjnym przypadająca na 100 osób w wieku produkcyjnym. Przez ludność w wieku produkcyjnym rozumie się osoby w wieku zdolności do pracy tj. mężczyźni w wieku 18 - 64 lat oraz kobiety w wieku 18 - 59.', 2024, 74.2, 'na 100 osób w wieku produkcyjnym'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Przyrost naturalny na 1 000 ludności', 'Różnica między liczbą urodzeń żywych a liczbą zgonów w danym roku (bez rozróżnienia na płeć).', 2024, -4.76, 'na 1000 mieszkańców'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik feminizacji', 'Wskaźnik feminizacji - wielkość demograficzna określająca ile kobiet przypada na 100 mężczyzn na danym terenie.', 2024, 106.59, 'kobiet na 100 mężczyzn'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik maskulinizacji', 'Wskaźnik maskulinizacji - wielkość demograficzna określająca ilu mężczyzn przypada na 100 kobiet na danym terenie.', 2024, 93.82, 'mężczyzn na 100 kobiet'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik gęstości zaludnienia', 'Wskaźnik gęstości zaludnienia - liczba mieszkańców przypadająca na 1 km².', 2024, 363.6, 'osób na 1 km²'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik urbanizacji', 'Wskaźnik urbanizacji - udział mieszkańców miast w liczbie mieszkańców ogółem. Do wyliczenia wskaźnika posłużono się danymi na temat ludności faktycznie zamieszkałej na dzień 31 XII każdego roku. Ludnośc faktycznie zamieszkała obejmuje: a) stałych mieszkańców, z wyjatkiem osób przebywających poza miejscem zamieszkania przez okres powyżej 3 miesięcy w kraju oraz obejmuje wszystkie osoby przebywajace za granicą (bez względu na okres ich nieobecności) b) osoby przebywające czasowo przez okres powyżej 3 miesięcy, przybyłe z innego miejsca w kraju. Dane za lata 2010 - 2021 bazują na wynikach Narodowego Spisu Powszechnego Ludności i Mieszkań 2011.', 2024, 50.97, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Małżeństwa na 1000 mieszkańców', 'Liczba zawartych małżeństw w przeliczeniu na 1000 mieszkańców.', 2024, 3.5, 'na 1000 mieszkańców'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Urodzenia na 1000 mieszkańców', 'Liczba urodzeń żywych w przeliczeniu na 1000 mieszkańców.', 2024, 6.21, 'na 1000 mieszkańców'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Zgony na 1000 mieszkańców', 'Liczba zgonów w przeliczeniu na 1000 mieszkańców.', 2024, 10.97, 'na 1000 mieszkańców'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik/ indeks starości', 'Relacja pokoleniowa dziadków i wnuczków, tj. liczba osób w wieku 65 i więcej lat przypadająca na 100 osób w wieku 0-14 lat', 2024, 150.0, 'osób 65+ na 100 dzieci do 14 lat'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Ludność w wieku 65+/ Współczynnik starości demograficznej', 'Relacja liczby osób w starszym wieku (65 lat i więcej) do ogólnej liczby ludności.', 2024, 21.44, '%'),
('oswiecimski', 'powiat oświęcimski', 'Ludność', 'Wskaźnik potencjalnego wsparcia', 'Liczba osób w wieku 15-64 lata przypadająca na 100 osób w wieku 65 lat i więcej. Przedstawia tzw. obciążenie - ile osób hipotetycznie pozostających na rynku pracy przypada na 1 osobę (100 osób) będącą już poza rykiem pracy (odwrotność cząstkowego współczynnika obciążenia demograficznego osobami starszymi).', 2024, 300.0, 'osób 15–64 na 100 osób 65+'),
('oswiecimski', 'powiat oświęcimski', 'Pomoc społeczna – kadra', 'Liczba mieszkańców na 1 pracownika socjalnego', 'Liczba mieszkańców przypadająca na jednego pracownika socjalnego zatrudnionego w ośrodku pomocy społecznej.', 2024, 1893.0, 'mieszkańców na 1 pracownika'),
('oswiecimski', 'powiat oświęcimski', 'Pomoc społeczna – kadra', 'Pracownicy socjalni OPS posiadający wyższe wykształcenie', 'Udział pracowników socjalnych posiadających wyższe wykształcenie w ogólnej licznie pracowników socjalnych.', 2024, 93.83, '%'),
