-- Wygenerowane przez data/import_powiaty.py --sql. Można uruchamiać wielokrotnie.
begin;
delete from powiaty_wskazniki where rok in (2024);
on conflict (powiat, wskaznik, rok) do update set nazwa = excluded.nazwa, kategoria = excluded.kategoria,
  opis = excluded.opis, wartosc = excluded.wartosc, jednostka = excluded.jednostka;
commit;
